<?php require_once '../config/app.php';require_once '../includes/security.php';start_secure_session();require_admin();$pdo=db();$id=(int)($_GET['id']??$_POST['id']??0);$error=null;$success=null;if($_SERVER['REQUEST_METHOD']==='POST'){if(!csrf_check($_POST['_csrf']??''))$error='Invalid request.';else{$p=$_POST['password']??'';$c=$_POST['confirm_password']??'';if(strlen($p)<8||$p!==$c)$error='Password must be at least 8 characters and match.';else{$pdo->prepare("UPDATE users SET password_hash=?,reset_token=NULL,reset_expires=NULL WHERE id=?")->execute([password_hash($p,PASSWORD_DEFAULT),$id]);$pdo->prepare("INSERT INTO audit_logs(admin_id,action,module,record_id,created_at) VALUES(?,?,?,?,NOW())")->execute([$_SESSION['admin_id'],'RESET_PASSWORD','users',$id]);$success='Password reset successfully.';}}}$page_title='Reset User Password';$asset_prefix='../';$home_link='../index.php';require '../includes/header.php';?><div class="form-wrap"><div class="form-card"><h1>Reset User Password</h1><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="alert success"><?=e($success)?></div><?php endif;?><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=e($id)?>"><label>New Password<input type="password" name="password" required></label><label>Confirm Password<input type="password" name="confirm_password" required></label><button class="btn btn-primary full">Reset Password</button></form></div></div><?php require '../includes/footer.php';?>